@js:(function(){
var s='';
try{s=String(src);}catch(e){}
if(s.length<500){s=String(result);}
var o=[],m,re=/\(\s*'([A-Za-z0-9+\/=]{40,})'\s*\)/g;
while((m=re.exec(s))!==null){o.push(java.base64Decode(m[1]));}
if(o.length<1){re=/'([A-Za-z0-9+\/=]{40,})'/g;while((m=re.exec(s))!==null){o.push(java.base64Decode(m[1]));}}
if(o.length>0){return o.join('\n');}
var seg=s,i=s.indexOf('<div class="word_read">');
if(i>-1){seg=s.slice(i);}
var ks=[seg.indexOf('<script language=javascript>'),seg.indexOf('<div class="footer"'),seg.indexOf('</body>'),seg.indexOf('相邻推荐')];
var kk=0;
for(var z=0;z<ks.length;z++){if(ks[z]>0){if(kk<1){kk=ks[z];}else{if(ks[z]<kk){kk=ks[z];}}}}
if(kk>0){seg=seg.slice(0,kk);}
seg=seg.replace(/<script[\s\S]*?<\/script>/gi,'');
seg=seg.replace(/<div class="read_btn"[\s\S]*?<\/div>/gi,'');
var mm=seg.match(/<p[\s\S]*?<\/p>/gi);
var out=[];
if(mm){for(var q=0;q<mm.length;q++){var t=mm[q];if(t.indexOf('请勿开启')<0){if(t.indexOf('相邻推荐')<0){if(t.indexOf('本站所有')<0){if(t.indexOf('Copyright')<0){out.push(t);}}}}}}
return out.join('\n');
})()

jsLib:
var hosts = [
    "https://www.suduguu.com",
    "https://shudugu.org",
    "https://sudugu520.com"
];

function getHosts() {
    return hosts;
}

function getServerHost() {
    var source = this.source;
    try {
        var config = JSON.parse(source.getVariable());
        if (config && config[0] && config[0].host) {
            return config[0].host;
        }
        return getHosts()[0];
    } catch (e) {
        return getHosts()[0];
    }
}

function getConfig() {
    var source = this.source;
    try {
        var configStr = source.getVariable();
        if (!configStr || configStr.trim() === "") {
            return { host: getHosts()[0] };
        }
        var config = JSON.parse(configStr);
        if (!config || !config.join || config.length === 0) {
            return { host: getHosts()[0] };
        }
        return config[0] || { host: getHosts()[0] };
    } catch (e) {
        return { host: getHosts()[0] };
    }
}

function setConfig(key, value) {
    var source = this.source;
    try {
        var config = getConfig.call(this);
        config[key] = value;
        source.setVariable(JSON.stringify([config]));
        return true;
    } catch (e) {
        return false;
    }
}

function setConfigs(obj) {
    var source = this.source;
    try {
        var config = getConfig.call(this);
        for (var k in obj) {
            if (obj.hasOwnProperty(k)) {
                config[k] = obj[k];
            }
        }
        source.setVariable(JSON.stringify([config]));
        return true;
    } catch (e) {
        return false;
    }
}

function checkConnectivity(host) {
    var timeout = 5000;
    var socket = null;
    try {
        var start = new Date().getTime();
        var jUrl = new Packages.java.net.URL(host);
        var hostname = jUrl.getHost();
        var port = jUrl.getPort();
        if (port === -1) { port = jUrl.getDefaultPort(); }
        socket = new Packages.java.net.Socket();
        var addr = new Packages.java.net.InetSocketAddress(hostname, port);
        socket.connect(addr, timeout);
        var latency = new Date().getTime() - start;
        return {ok: true, latency: latency};
    } catch (e) {
        return {ok: false, latency: -1, err: String(e)};
    } finally {
        try { if (socket !== null) { socket.close(); } } catch (e2) {}
    }
}

function autoSelectHost() {
    var allHosts = getHosts();
    var details = [];
    var best = null;
    var bestLatency = -1;
    for (var i = 0; i < allHosts.length; i++) {
        var r = checkConnectivity.call(this, allHosts[i]);
        r.host = allHosts[i];
        details.push(r);
        if (r.ok && (bestLatency < 0 || r.latency < bestLatency)) {
            best = allHosts[i];
            bestLatency = r.latency;
        }
    }
    if (best !== null) {
        setConfig.call(this, 'host', best);
    }
    return {success: best !== null, host: best, details: details};
}

