var book=["玄幻魔法","武侠修真",
"都市言情","历史军事","侦探推理",
"网游动漫","科幻小说","恐怖灵异",
"言情小说","其他类型","经部","史书",
"子部","集部","四库之外","古典书籍",
"诗歌","宋词",["排行","/top/allvisit"],
["新书","/top/postdate"],
["完本小说","/fulltop/allvisit"]];

sort=book.map((a,i)=>{
	if(i<book.length-3){
		i++; title=a;
		url=`/sort/${i}/{{page}}.html`;
		}else{
			title=String(a[0]);
			url=`${a[1]}/{{page}}.html`;
			}
			json=({
    "title": title,
    "url": url,
    "style": {
      "layout_flexGrow": 1,
       "layout_flexBasisPercent": 0.25,
    }
   });
   return json
	});

JSON.stringify(sort)

loginCheckJs:
var url=result.url(),
code=result.code(),
body=result.body();
err=/503 Service Temporarily/;
while(code==503||err.test(body)){
	java.log("网页出错，重新加载！")
	result=java.connect(url)
	code=result.code();
	body=result.body();
	}
result;

